import java.util.*;

public class e {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int testCases = 1;
        while (testCases > 0) {
            int n = input.nextInt();
            int[] a = new int[3];
            int[] b = new int[3];
            for (int index = 0; index < 3; index++) {
                a[index] = input.nextInt();
            }
            for (int index = 0; index < 3; index++) {
                b[index] = input.nextInt();
            }
            int result1 = 0;
            for (int i = 0; i < 3; i++) {
                result1 += Math.min(a[i], b[i] + b[(i + 2) % 3]);
            }
            System.out.print((n - result1) + " ");
            int result2 = 0;
            for (int i = 0; i < 3; i++) {
                result2 += Math.min(a[i], b[(i + 1) % 3]);
            }
            System.out.println(result2);
            testCases--;
        }
    }
}
